/**
 * The part catalogue. Every visible component on every machine (player or enemy)
 * is one of these definitions, and every stat here feeds the physical simulation.
 */
import type { MachineClass, PartDef, PartCategory, Rarity, SocketType } from '../types';
import { sock, surf, sym } from './sockets';

const ALL: MachineClass[] = ['ground', 'air', 'mech'];
const G: MachineClass[] = ['ground'];
const A: MachineClass[] = ['air'];
const M: MachineClass[] = ['mech'];

type Def = Omit<PartDef, 'size' | 'classes' | 'mount' | 'armor' | 'family' | 'stats'> &
  Partial<Pick<PartDef, 'size' | 'classes' | 'mount' | 'armor' | 'family' | 'stats'>>;

const MOUNT_BY_CAT: Partial<Record<PartCategory, SocketType[]>> = {
  frame: [],
  cockpit: ['cockpit'],
  suspension: ['axle'],
  wheel: ['hub'],
  track: ['track'],
  leg: ['hip'],
  actuator: ['joint'],
  foot: ['foot'],
  arm: ['shoulder'],
  melee: ['hand'],
  weapon: ['surface', 'hand', 'hardpoint'],
};

function P(d: Def): PartDef {
  return {
    size: [0.5, 0.5, 0.5],
    classes: ALL,
    mount: MOUNT_BY_CAT[d.category] ?? ['surface'],
    armor: 4,
    family: 'scrap',
    stats: {},
    ...d,
  } as PartDef;
}

