export const PARTS: PartDef[] = [
  ...FRAMES,
  ...COCKPITS,
  ...ENGINES,
  ...GENERATORS,
  ...BATTERIES,
  ...FUEL,
  ...COOLING,
  ...TRANSMISSIONS,
  ...SUSPENSION,
  ...WHEELS,
  ...TRACKS,
  ...GROUND_MISC,
  ...ARMOR,
  ...WEAPONS,
  ...AIR,
  ...MECH,
];

export const PART_MAP = new Map<string, PartDef>(PARTS.map((p) => [p.id, p]));

export function getPart(id: string): PartDef {
  const p = PART_MAP.get(id);
  if (!p) throw new Error(`Unknown part ${id}`);
  return p;
}

export function registerParts(defs: PartDef[]) {
  for (const d of defs) {
    PARTS.push(d);
    PART_MAP.set(d.id, d);
  }
}

export function partsOfRarity(r: Rarity) {
  return PARTS.filter((p) => p.rarity === r);
}
